// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint8 timestampIncrement) public {
        vm.assume(amount == 10 ether);
        vm.assume(timestampIncrement > 0);

        vm.deal(address(this), amount);
        (bool ok1,) = address(c).call{value: amount}("");
        assertTrue(ok1);

        vm.warp(block.timestamp + timestampIncrement);
        vm.deal(address(this), amount);
        (bool ok2,) = address(c).call{value: amount}("");
        assertTrue(ok2);
    }
}
